class Solution {
public:
    int countDominantElements(vector<int>& nums) {
        int n = nums.size();
        int cnt = 0;
        for (int i = 0; i < n; ++i) {
            if (i == 0) {
                if (n == 1 || nums[i] >= nums[i + 1]) ++cnt;
            } else if (i == n - 1) {
                if (nums[i] >= nums[i - 1]) ++cnt;
            } else {
                long long left = nums[i - 1];
                long long right = nums[i + 1];
                long long cur = nums[i];
                if (2LL * cur >= left + right) ++cnt;
            }
        }
        return cnt;
    }
};
